            padding: 20px;
            box-sizing: border-box;
        }
        .custom-modal-overlay.is-active {
            opacity: 1;
            pointer-events: auto;
        }
        .custom-modal-wrapper {
            background: #fff;
            padding: 30px;
            border-radius: 8px;
            max-width: 500px;
            width: 100%;
            box-shadow: 0 4px 15px rgba(0,0,0,0.2);
            position: relative;
            box-sizing: border-box;

            max-height: 85vh;
            overflow-y: auto;
        }
        .custom-modal-close {
            position: absolute;
            top: 15px;
            right: 15px;
            background: none;
            border: none;
            font-size: 20px;
            cursor: pointer;
            color: #333;
            z-index: 10;
        }


